import AppKit
import SwiftUI

/// Design tokens (UI-CONCEPT §2.2, DESIGN §11.8). Views never use raw hex: every role is a Color Set in
/// `Assets.xcassets/Colors` with Any/Dark and High Contrast variants (generated by `native/Tools/ui/gen_colors.py`).
extension Color {
    enum lp {
        /// Brand foreground: glyphs, chart rx line, tinted text, links on brand surfaces.
        static let sage = Color("lp.sage")
        /// Connected state, always with the closed-lock shape.
        static let protected = Color("lp.protected")
        /// Connecting, reasserting (glyph variant, ≥ 3:1).
        static let transition = Color("lp.transition")
        /// Transition text variant (≥ 4.5:1 in light mode).
        static let transitionText = Color("lp.transitionText")
        /// Paused, auth needed, DNS unverified, Blocked (glyph variant).
        static let attention = Color("lp.attention")
        static let attentionText = Color("lp.attentionText")
        /// Errors, destructive (glyph and fill).
        static let critical = Color("lp.critical")
        static let criticalText = Color("lp.criticalText")
        /// Brand surfaces only (§2.5).
        static let canvas = Color("lp.canvas")
        static let grouped = Color("lp.grouped")
        /// Hero card and menu header card.
        static let card = Color("lp.card")
        /// Editor and logs.
        static let sunken = Color("lp.sunken")
        /// Grouped rows under a tile (Activity and Diagnostics tables): navy in dark mode, white in light mode.
        static let panel = Color("lp.panel")
        /// Text field fill and border (`lpField()`): close to the window background, a soft border.
        static let field = Color("lp.field")
        static let fieldBorder = Color("lp.fieldBorder")
        /// Text on brand surfaces.
        static let label = Color("lp.label")
        static let label2 = Color("lp.label2")
        /// Placeholder, disabled, decoration only (fails 4.5:1 by design).
        static let label3 = Color("lp.label3")
        /// Borders that carry meaning (≥ 3:1).
        static let stroke = Color("lp.stroke")
        /// Decorative separators only.
        static let hairline = Color("lp.hairline")
        static let rx = Color("lp.rx")
        /// tx is also dashed in charts.
        static let tx = Color("lp.tx")
        /// Link text and the 2 pt focus ring: AccentColor is too dark for both on the dark window (2.9:1), so dark mode
        /// uses the lighter sage (#80ae9a); light is a deeper sage (text 4.5:1, ring 3:1).
        static let accentText = Color("lp.accentText")
        static let connectFill = Color("lp.connectFill")
        static let connectLabel = Color("lp.connectLabel")
        static let navy = Color("lp.navy")
        /// The app icon's background (AppIcon.icon): off-white in light, navy in dark. Only `AppIconTile` uses it.
        static let iconTile = Color("lp.iconTile")

        // Pastel palette (UI-CONCEPT §2.2a): everything outside the status tiles (hero, menu header, tray tiles).
        /// Pastel surfaces: badges, chips, banners, chart fills. Text on them is `onPastel` / `onPastel2`.
        static let pastelSage = Color("lp.pastelSage")
        static let pastelAmber = Color("lp.pastelAmber")
        static let pastelRose = Color("lp.pastelRose")
        static let pastelTeal = Color("lp.pastelTeal")
        static let pastelYellow = Color("lp.pastelYellow")
        static let onPastel = Color("lp.onPastel")
        static let onPastel2 = Color("lp.onPastel2")
        /// Marks on canvas surfaces (icons, chart lines, ≥ 3:1): medium tones in light mode, pastels in dark mode.
        static let softSage = Color("lp.softSage")
        static let softAmber = Color("lp.softAmber")
        static let softRose = Color("lp.softRose")
        static let softTeal = Color("lp.softTeal")
        static let softYellow = Color("lp.softYellow")
        /// Disconnected: deliberately not red (§2.2).
        static let unprotected = Color(nsColor: .secondaryLabelColor)
    }
}

extension NSColor {
    enum lp {
        static let sage = NSColor(named: "lp.sage")!
        static let protected = NSColor(named: "lp.protected")!
        static let attention = NSColor(named: "lp.attention")!
        static let critical = NSColor(named: "lp.critical")!
        static let navy = NSColor(named: "lp.navy")!
        static let trayIdle = NSColor(named: "lp.trayIdle")!
        static let trayProtected = NSColor(named: "lp.trayProtected")!
        static let trayAttention = NSColor(named: "lp.trayAttention")!
    }
}
